from __future__ import annotations

import platform
import re
import subprocess
from datetime import datetime, timedelta
from typing import Callable

from secretscan.model import Confidence, Finding, Module, ModuleStatus, Severity
from secretscan.redact import hash_value
from secretscan.redact import value as redact_value
from secretscan.rules.entropy import shannon_entropy
from secretscan.scanner.content import fingerprint

_STALE_AFTER = timedelta(days=2 * 365)

_KEYCHAIN_LIST_RE = re.compile(r'^\s*"([a-z]{4})"<blob>="((?:[^"\\]|\\.)*)"', re.MULTILINE)
_KEYCHAIN_CDAT_RE = re.compile(r'^\s*"cdat"<timedate>=0x[0-9A-Fa-f]+\s*"(\d{14})Z?', re.MULTILINE)


def _keychain_finding(
    rule_id: str, description: str, severity: Severity, service: str, account: str
) -> Finding:
    label = f"{service}|{account}"
    h = hash_value(label)
    return Finding(
        fingerprint=fingerprint(rule_id, h, "keychain"),
        rule_id=rule_id,
        description=description,
        severity=severity,
        confidence=Confidence.MEDIUM,
        module=Module.KEYCHAIN,
        location="Keychain item",
        redacted_value=redact_value(label),
        service=redact_value(service),
        account=redact_value(account),
        secret_hash=h,
        tags=["keychain"],
        detected_at=datetime.utcnow(),
    )


def keychain_scan(emit: Callable[[Finding], None]) -> ModuleStatus:
    status = ModuleStatus(module=Module.KEYCHAIN)

    if platform.system() != "Darwin":
        status.note = "skipped: unsupported platform (macOS only)"
        return status

    status.attempted = 1
    try:
        result = subprocess.run(
            ["security", "dump-keychain"],
            capture_output=True, text=True, timeout=30,
        )
        dump = result.stdout
    except (subprocess.SubprocessError, FileNotFoundError) as e:
        status.skipped = 1
        status.note = f"could not run `security dump-keychain`: {e}"
        return status

    status.accessed = 1
    status.note = "metadata only (service/account names, creation dates); item secret values are never decrypted"

    items: list[dict] = []
    for block in dump.split("keychain: "):
        if not block:
            continue
        item: dict = {"service": "", "account": "", "created_at": None}
        for m in _KEYCHAIN_LIST_RE.finditer(block):
            if m.group(1) == "svce":
                item["service"] = m.group(2)
            elif m.group(1) == "acct":
                item["account"] = m.group(2)
        cdat = _KEYCHAIN_CDAT_RE.search(block)
        if cdat:
            try:
                item["created_at"] = datetime.strptime(cdat.group(1), "%Y%m%d%H%M%S")
            except ValueError:
                pass
        if item["service"] or item["account"]:
            items.append(item)

    seen: dict[str, int] = {}
    for it in items:
        key = f"{it['service']}|{it['account']}"
        seen[key] = seen.get(key, 0) + 1

    now = datetime.utcnow()
    for it in items:
        svc, acct = it["service"], it["account"]
        if not svc and not acct:
            continue

        if seen.get(f"{svc}|{acct}", 0) > 1:
            emit(_keychain_finding(
                "keychain-duplicate-entry",
                "Duplicate keychain entry for the same service/account",
                Severity.LOW, svc, acct,
            ))

        if it["created_at"] and (now - it["created_at"]) > _STALE_AFTER:
            emit(_keychain_finding(
                "keychain-stale-entry",
                "Keychain entry older than 2 years - review whether it's still needed",
                Severity.LOW, svc, acct,
            ))

        if shannon_entropy(acct) >= 4.2 and len(acct) >= 16:
            emit(_keychain_finding(
                "keychain-high-entropy-account",
                "Keychain account name looks like a token/secret rather than a username",
                Severity.MEDIUM, svc, acct,
            ))

    return status
